/**
 * @file door_control.h
 * @brief 电机控制模块头文件
 *
 * 本文件定义了门锁电机控制的接口和数据结构。
 *
 * Copyright (C) 2026 weihedui Team
 * Licensed under the Apache License, Version 2.0
 */

#ifndef __DOOR_CONTROL_H__
#define __DOOR_CONTROL_H__

#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

/**
 * @brief 电机命令定义
 */
typedef enum {
    MOTOR_CMD_OPEN,           /**< 开门命令 */
    MOTOR_CMD_CLOSE,          /**< 关门命令 */
    MOTOR_CMD_LOCK,           /**< 锁门命令 */
    MOTOR_CMD_STOP,           /**< 停止命令 */
    MOTOR_CMD_EMERGENCY_STOP  /**< 紧急停止命令 */
} motor_cmd_t;

/**
 * @brief 电机状态定义
 */
typedef enum {
    MOTOR_STATE_IDLE,         /**< 空闲状态 */
    MOTOR_STATE_OPENING,      /**< 开门中 */
    MOTOR_STATE_CLOSING,      /**< 关门中 */
    MOTOR_STATE_LOCKING,      /**< 锁门中 */
    MOTOR_STATE_ERROR         /**< 错误状态 */
} motor_state_t;

/**
 * @brief 电机配置结构体
 */
typedef struct {
    uint8_t open_gpio_pin;    /**< 开门电机GPIO引脚 */
    uint8_t close_gpio_pin;   /**< 关门电机GPIO引脚 */
    uint8_t lock_gpio_pin;    /**< 锁门电机GPIO引脚 */
    uint8_t buzzer_gpio_pin;  /**< 蜂鸣器GPIO引脚 */
    uint32_t open_timeout_ms; /**< 开门超时时间(ms) */
    uint32_t close_timeout_ms;/**< 关门超时时间(ms) */
    uint32_t lock_timeout_ms; /**< 锁门超时时间(ms) */
} motor_config_t;

/**
 * @brief 初始化电机控制模块
 *
 * @param config 电机配置参数
 * @return int 0: 成功, -1: 失败
 */
int door_control_init(const motor_config_t *config);

/**
 * @brief 反初始化电机控制模块
 *
 * @return int 0: 成功, -1: 失败
 */
int door_control_deinit(void);

/**
 * @brief 控制电机
 *
 * @param cmd 电机命令
 * @return int 0: 成功, -1: 失败
 */
int motor_control(motor_cmd_t cmd);

/**
 * @brief 获取电机状态
 *
 * @return motor_state_t 当前电机状态
 */
motor_state_t motor_get_state(void);

/**
 * @brief 获取电机状态字符串
 *
 * @param state 电机状态
 * @return const char* 状态字符串
 */
const char *motor_state_to_string(motor_state_t state);

/**
 * @brief 启动蜂鸣器报警
 *
 * @param duration_ms 报警持续时间(ms)
 * @return int 0: 成功, -1: 失败
 */
int buzzer_alarm(uint32_t duration_ms);

/**
 * @brief 停止蜂鸣器报警
 *
 * @return int 0: 成功, -1: 失败
 */
int buzzer_stop(void);

#ifdef __cplusplus
}
#endif

#endif /* __DOOR_CONTROL_H__ */

/**
 * @file door_control.c
 * @brief 电机控制模块实现
 *
 * 本文件实现了门锁电机的控制逻辑，包括：
 * - GPIO输出控制（开门/关门/锁门电机、蜂鸣器）
 * - 状态机管理（空闲、开门中、关门中、锁门中）
 * - 超时保护机制
 * - 紧急停止功能
 *
 * Copyright (C) 2026 weihedui Team
 * Licensed under the Apache License, Version 2.0
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

#include "door_control.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define MOTOR_TASK_STACK_SIZE    4096
#define MOTOR_CHECK_INTERVAL_MS 50

/* GPIO模拟定义（实际硬件需要替换为真实GPIO操作） */
#ifndef CONFIG_USE_REAL_GPIO
#define GPIO_HIGH 1
#define GPIO_LOW  0
#endif

/****************************************************************************
 * Private Types
 ****************************************************************************/

/**
 * @brief 电机控制上下文结构体
 */
typedef struct {
    motor_state_t state;           /**< 当前电机状态 */
    motor_config_t config;         /**< 电机配置 */
    bool initialized;              /**< 是否已初始化 */
    bool timeout_enabled;          /**< 超时保护是否启用 */
    struct timespec start_time;    /**< 操作开始时间 */
    pthread_mutex_t mutex;         /**< 互斥锁 */
    pthread_t timeout_thread;      /**< 超时检测线程 */
    bool timeout_running;          /**< 超时检测线程运行标志 */
} motor_context_t;

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static int gpio_write(uint8_t pin, uint8_t value);
static void *timeout_task(void *arg);
static uint32_t get_elapsed_ms(const struct timespec *start);
static int start_timeout_check(void);
static int stop_timeout_check(void);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static motor_context_t g_motor_ctx = {
    .state = MOTOR_STATE_IDLE,
    .initialized = false,
    .timeout_enabled = true,
    .timeout_running = false,
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/**
 * @brief GPIO写操作（模拟实现）
 *
 * @param pin GPIO引脚号
 * @param value GPIO电平值
 * @return int 0: 成功, -1: 失败
 */
static int gpio_write(uint8_t pin, uint8_t value)
{
    /* TODO: 替换为实际的GPIO驱动调用 */
    printf("[MOTOR] GPIO %d -> %s\n", pin, value ? "HIGH" : "LOW");
    return 0;
}

/**
 * @brief 获取已经过的时间（毫秒）
 *
 * @param start 起始时间
 * @return uint32_t 经过的毫秒数
 */
static uint32_t get_elapsed_ms(const struct timespec *start)
{
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    uint32_t elapsed_ms = (now.tv_sec - start->tv_sec) * 1000 +
                          (now.tv_nsec - start->tv_nsec) / 1000000;
    return elapsed_ms;
}

/**
 * @brief 超时检测任务
 *
 * @param arg 任务参数（未使用）
 * @return void* 返回值（未使用）
 */
static void *timeout_task(void *arg)
{
    (void)arg;

    while (g_motor_ctx.timeout_running) {
        usleep(MOTOR_CHECK_INTERVAL_MS * 1000);

        pthread_mutex_lock(&g_motor_ctx.mutex);

        if (g_motor_ctx.state == MOTOR_STATE_IDLE ||
            g_motor_ctx.state == MOTOR_STATE_ERROR) {
            pthread_mutex_unlock(&g_motor_ctx.mutex);
            continue;
        }

        uint32_t elapsed = get_elapsed_ms(&g_motor_ctx.start_time);
        uint32_t timeout = 0;

        switch (g_motor_ctx.state) {
        case MOTOR_STATE_OPENING:
            timeout = g_motor_ctx.config.open_timeout_ms;
            break;
        case MOTOR_STATE_CLOSING:
            timeout = g_motor_ctx.config.close_timeout_ms;
            break;
        case MOTOR_STATE_LOCKING:
            timeout = g_motor_ctx.config.lock_timeout_ms;
            break;
        default:
            break;
        }

        if (timeout > 0 && elapsed >= timeout) {
            printf("[MOTOR] Timeout! State: %s, Elapsed: %u ms, Timeout: %u ms\n",
                   motor_state_to_string(g_motor_ctx.state), elapsed, timeout);

            /* 停止所有电机 */
            gpio_write(g_motor_ctx.config.open_gpio_pin, GPIO_LOW);
            gpio_write(g_motor_ctx.config.close_gpio_pin, GPIO_LOW);
            gpio_write(g_motor_ctx.config.lock_gpio_pin, GPIO_LOW);

            /* 设置错误状态 */
            g_motor_ctx.state = MOTOR_STATE_ERROR;

            /* 触发蜂鸣器报警 */
            buzzer_alarm(1000);
        }

        pthread_mutex_unlock(&g_motor_ctx.mutex);
    }

    return NULL;
}

/**
 * @brief 启动超时检测
 *
 * @return int 0: 成功, -1: 失败
 */
static int start_timeout_check(void)
{
    if (g_motor_ctx.timeout_running) {
        return 0;
    }

    g_motor_ctx.timeout_running = true;

    int ret = pthread_create(&g_motor_ctx.timeout_thread, NULL,
                             timeout_task, NULL);
    if (ret != 0) {
        printf("[MOTOR] Failed to create timeout thread: %d\n", ret);
        g_motor_ctx.timeout_running = false;
        return -1;
    }

    return 0;
}

/**
 * @brief 停止超时检测
 *
 * @return int 0: 成功, -1: 失败
 */
static int stop_timeout_check(void)
{
    if (!g_motor_ctx.timeout_running) {
        return 0;
    }

    g_motor_ctx.timeout_running = false;
    pthread_join(g_motor_ctx.timeout_thread, NULL);

    return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int door_control_init(const motor_config_t *config)
{
    if (config == NULL) {
        printf("[MOTOR] Error: config is NULL\n");
        return -1;
    }

    if (g_motor_ctx.initialized) {
        printf("[MOTOR] Warning: already initialized\n");
        return 0;
    }

    /* 保存配置 */
    memcpy(&g_motor_ctx.config, config, sizeof(motor_config_t));

    /* 初始化互斥锁 */
    pthread_mutex_init(&g_motor_ctx.mutex, NULL);

    /* 初始化GPIO */
    gpio_write(config->open_gpio_pin, GPIO_LOW);
    gpio_write(config->close_gpio_pin, GPIO_LOW);
    gpio_write(config->lock_gpio_pin, GPIO_LOW);
    gpio_write(config->buzzer_gpio_pin, GPIO_LOW);

    /* 设置初始状态 */
    g_motor_ctx.state = MOTOR_STATE_IDLE;
    g_motor_ctx.initialized = true;

    /* 启动超时检测 */
    if (g_motor_ctx.timeout_enabled) {
        start_timeout_check();
    }

    printf("[MOTOR] Initialized successfully\n");
    printf("[MOTOR]   Open GPIO: %d\n", config->open_gpio_pin);
    printf("[MOTOR]   Close GPIO: %d\n", config->close_gpio_pin);
    printf("[MOTOR]   Lock GPIO: %d\n", config->lock_gpio_pin);
    printf("[MOTOR]   Buzzer GPIO: %d\n", config->buzzer_gpio_pin);

    return 0;
}

int door_control_deinit(void)
{
    if (!g_motor_ctx.initialized) {
        return 0;
    }

    /* 停止超时检测 */
    stop_timeout_check();

    /* 停止所有电机 */
    pthread_mutex_lock(&g_motor_ctx.mutex);

    gpio_write(g_motor_ctx.config.open_gpio_pin, GPIO_LOW);
    gpio_write(g_motor_ctx.config.close_gpio_pin, GPIO_LOW);
    gpio_write(g_motor_ctx.config.lock_gpio_pin, GPIO_LOW);
    gpio_write(g_motor_ctx.config.buzzer_gpio_pin, GPIO_LOW);

    g_motor_ctx.state = MOTOR_STATE_IDLE;
    g_motor_ctx.initialized = false;

    pthread_mutex_unlock(&g_motor_ctx.mutex);

    /* 销毁互斥锁 */
    pthread_mutex_destroy(&g_motor_ctx.mutex);

    printf("[MOTOR] Deinitialized\n");

    return 0;
}

int motor_control(motor_cmd_t cmd)
{
    if (!g_motor_ctx.initialized) {
        printf("[MOTOR] Error: not initialized\n");
        return -1;
    }

    pthread_mutex_lock(&g_motor_ctx.mutex);

    printf("[MOTOR] Command: %d, Current state: %s\n",
           cmd, motor_state_to_string(g_motor_ctx.state));

    switch (cmd) {
    case MOTOR_CMD_OPEN:
        /* 停止其他电机 */
        gpio_write(g_motor_ctx.config.close_gpio_pin, GPIO_LOW);
        gpio_write(g_motor_ctx.config.lock_gpio_pin, GPIO_LOW);
        /* 启动开门电机 */
        gpio_write(g_motor_ctx.config.open_gpio_pin, GPIO_HIGH);
        g_motor_ctx.state = MOTOR_STATE_OPENING;
        clock_gettime(CLOCK_MONOTONIC, &g_motor_ctx.start_time);
        break;

    case MOTOR_CMD_CLOSE:
        /* 停止其他电机 */
        gpio_write(g_motor_ctx.config.open_gpio_pin, GPIO_LOW);
        gpio_write(g_motor_ctx.config.lock_gpio_pin, GPIO_LOW);
        /* 启动关门电机 */
        gpio_write(g_motor_ctx.config.close_gpio_pin, GPIO_HIGH);
        g_motor_ctx.state = MOTOR_STATE_CLOSING;
        clock_gettime(CLOCK_MONOTONIC, &g_motor_ctx.start_time);
        break;

    case MOTOR_CMD_LOCK:
        /* 停止其他电机 */
        gpio_write(g_motor_ctx.config.open_gpio_pin, GPIO_LOW);
        gpio_write(g_motor_ctx.config.close_gpio_pin, GPIO_LOW);
        /* 启动锁门电机 */
        gpio_write(g_motor_ctx.config.lock_gpio_pin, GPIO_HIGH);
        g_motor_ctx.state = MOTOR_STATE_LOCKING;
        clock_gettime(CLOCK_MONOTONIC, &g_motor_ctx.start_time);
        break;

    case MOTOR_CMD_STOP:
    case MOTOR_CMD_EMERGENCY_STOP:
        /* 停止所有电机 */
        gpio_write(g_motor_ctx.config.open_gpio_pin, GPIO_LOW);
        gpio_write(g_motor_ctx.config.close_gpio_pin, GPIO_LOW);
        gpio_write(g_motor_ctx.config.lock_gpio_pin, GPIO_LOW);
        g_motor_ctx.state = MOTOR_STATE_IDLE;
        break;

    default:
        printf("[MOTOR] Error: unknown command %d\n", cmd);
        pthread_mutex_unlock(&g_motor_ctx.mutex);
        return -1;
    }

    pthread_mutex_unlock(&g_motor_ctx.mutex);

    printf("[MOTOR] New state: %s\n", motor_state_to_string(g_motor_ctx.state));

    return 0;
}

motor_state_t motor_get_state(void)
{
    return g_motor_ctx.state;
}

const char *motor_state_to_string(motor_state_t state)
{
    switch (state) {
    case MOTOR_STATE_IDLE:    return "IDLE";
    case MOTOR_STATE_OPENING: return "OPENING";
    case MOTOR_STATE_CLOSING: return "CLOSING";
    case MOTOR_STATE_LOCKING: return "LOCKING";
    case MOTOR_STATE_ERROR:   return "ERROR";
    default:                  return "UNKNOWN";
    }
}

int buzzer_alarm(uint32_t duration_ms)
{
    if (!g_motor_ctx.initialized) {
        return -1;
    }

    printf("[BUZZER] Alarm for %u ms\n", duration_ms);

    gpio_write(g_motor_ctx.config.buzzer_gpio_pin, GPIO_HIGH);
    usleep(duration_ms * 1000);
    gpio_write(g_motor_ctx.config.buzzer_gpio_pin, GPIO_LOW);

    return 0;
}

int buzzer_stop(void)
{
    if (!g_motor_ctx.initialized) {
        return -1;
    }

    printf("[BUZZER] Stop\n");

    gpio_write(g_motor_ctx.config.buzzer_gpio_pin, GPIO_LOW);

    return 0;
}

/**
 * @file safety.h
 * @brief 安全模块头文件
 *
 * 本文件定义了防夹保护功能的接口和数据结构。
 *
 * Copyright (C) 2026 weihedui Team
 * Licensed under the Apache License, Version 2.0
 */

#ifndef __SAFETY_H__
#define __SAFETY_H__

#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

/**
 * @brief 雷达状态定义
 */
typedef enum {
    RADAR_STATE_NO_TARGET,    /**< 无目标 */
    RADAR_STATE_MOVING,       /**< 目标移动中 */
    RADAR_STATE_STATIONARY    /**< 目标静止 */
} radar_state_t;

/**
 * @brief 雷达数据结构体
 */
typedef struct {
    radar_state_t state;      /**< 雷达状态 */
    uint16_t distance_cm;     /**< 距离（厘米） */
    uint16_t energy;          /**< 能量值 */
    uint32_t timestamp;       /**< 时间戳 */
} radar_result_t;

/**
 * @brief 安全配置结构体
 */
typedef struct {
    uint8_t anti_pinch_threshold;  /**< 防夹检测阈值（连续检测次数） */
    uint32_t check_interval_ms;    /**< 检测间隔（毫秒） */
    uint16_t detection_range_cm;   /**< 检测范围（厘米） */
} safety_config_t;

/**
 * @brief 初始化安全模块
 *
 * @param config 安全配置参数
 * @return int 0: 成功, -1: 失败
 */
int safety_init(const safety_config_t *config);

/**
 * @brief 反初始化安全模块
 *
 * @return int 0: 成功, -1: 失败
 */
int safety_deinit(void);

/**
 * @brief 启动防夹检测
 *
 * @return int 0: 成功, -1: 失败
 */
int safety_start(void);

/**
 * @brief 停止防夹检测
 *
 * @return int 0: 成功, -1: 失败
 */
int safety_stop(void);

/**
 * @brief 获取雷达状态
 *
 * @param result 雷达数据输出
 * @return int 0: 成功, -1: 失败
 */
int radar_get_status(radar_result_t *result);

/**
 * @brief 检查是否触发防夹保护
 *
 * @return true: 触发防夹保护, false: 未触发
 */
bool safety_is_anti_pinch_triggered(void);

/**
 * @brief 重置防夹检测状态
 */
void safety_reset(void);

#ifdef __cplusplus
}
#endif

#endif /* __SAFETY_H__ */

/**
 * @file safety.c
 * @brief 安全模块实现
 *
 * 本文件实现了门锁的防夹保护功能，包括：
 * - 雷达数据实时监测
 * - 防夹判断逻辑（连续3次检测到目标触发保护）
 * - 紧急响应（停止电机、反向开门、蜂鸣器报警）
 * - 状态恢复机制
 *
 * Copyright (C) 2026 weihedui Team
 * Licensed under the Apache License, Version 2.0
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

#include "safety.h"
#include "door_control.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define SAFETY_TASK_STACK_SIZE  4096
#define DEFAULT_CHECK_INTERVAL  20   /* 20ms */
#define DEFAULT_THRESHOLD       3    /* 连续3次 */
#define DEFAULT_RANGE_CM        100  /* 100cm */

/****************************************************************************
 * Private Types
 ****************************************************************************/

/**
 * @brief 安全模块上下文结构体
 */
typedef struct {
    bool initialized;              /**< 是否已初始化 */
    bool running;                  /**< 检测任务是否运行 */
    bool anti_pinch_triggered;     /**< 防夹是否触发 */
    safety_config_t config;        /**< 安全配置 */
    uint8_t detect_count;          /**< 连续检测计数 */
    pthread_t safety_thread;       /**< 安全检测线程 */
    pthread_mutex_t mutex;         /**< 互斥锁 */
} safety_context_t;

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static void *safety_task(void *arg);
static int radar_read_data(radar_result_t *result);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static safety_context_t g_safety_ctx = {
    .initialized = false,
    .running = false,
    .anti_pinch_triggered = false,
    .detect_count = 0,
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/**
 * @brief 读取雷达数据（模拟实现）
 *
 * @param result 雷达数据输出
 * @return int 0: 成功, -1: 失败
 */
static int radar_read_data(radar_result_t *result)
{
    if (result == NULL) {
        return -1;
    }

    /* TODO: 替换为实际的雷达驱动调用 */
    /* 模拟随机雷达数据 */
    static uint32_t call_count = 0;
    call_count++;

    result->timestamp = time(NULL);

    /* 模拟：每100次调用检测到一次目标 */
    if (call_count % 100 < 10) {
        result->state = RADAR_STATE_MOVING;
        result->distance_cm = 50;
        result->energy = 80;
    } else {
        result->state = RADAR_STATE_NO_TARGET;
        result->distance_cm = 0;
        result->energy = 0;
    }

    return 0;
}

/**
 * @brief 安全检测任务
 *
 * @param arg 任务参数（未使用）
 * @return void* 返回值（未使用）
 */
static void *safety_task(void *arg)
{
    (void)arg;

    radar_result_t radar;

    printf("[SAFETY] Detection task started\n");

    while (g_safety_ctx.running) {
        usleep(g_safety_ctx.config.check_interval_ms * 1000);

        /* 仅在关门过程中检测 */
        motor_state_t motor_state = motor_get_state();
        if (motor_state != MOTOR_STATE_CLOSING) {
            /* 不在关门状态，重置计数 */
            pthread_mutex_lock(&g_safety_ctx.mutex);
            g_safety_ctx.detect_count = 0;
            pthread_mutex_unlock(&g_safety_ctx.mutex);
            continue;
        }

        /* 读取雷达数据 */
        if (radar_read_data(&radar) != 0) {
            printf("[SAFETY] Failed to read radar data\n");
            continue;
        }

        pthread_mutex_lock(&g_safety_ctx.mutex);

        /* 检测到目标 */
        if (radar.state == RADAR_STATE_MOVING ||
            radar.state == RADAR_STATE_STATIONARY) {

            /* 检查是否在检测范围内 */
            if (radar.distance_cm <= g_safety_ctx.config.detection_range_cm) {
                g_safety_ctx.detect_count++;

                printf("[SAFETY] Target detected! Count: %d/%d, Distance: %d cm\n",
                       g_safety_ctx.detect_count,
                       g_safety_ctx.config.anti_pinch_threshold,
                       radar.distance_cm);

                /* 连续检测次数达到阈值 */
                if (g_safety_ctx.detect_count >= g_safety_ctx.config.anti_pinch_threshold) {
                    printf("[SAFETY] *** ANTI-PINCH TRIGGERED! ***\n");

                    /* 标记防夹已触发 */
                    g_safety_ctx.anti_pinch_triggered = true;

                    /* 紧急停止电机 */
                    motor_control(MOTOR_CMD_EMERGENCY_STOP);

                    /* 反向开门 */
                    usleep(100000); /* 等待100ms */
                    motor_control(MOTOR_CMD_OPEN);

                    /* 触发蜂鸣器报警 */
                    buzzer_alarm(500);

                    /* 等待目标离开 */
                    printf("[SAFETY] Waiting for target to leave...\n");
                    while (g_safety_ctx.running) {
                        usleep(100000); /* 100ms */
                        if (radar_read_data(&radar) == 0) {
                            if (radar.state == RADAR_STATE_NO_TARGET) {
                                printf("[SAFETY] Target left, resuming operation\n");
                                break;
                            }
                        }
                    }

                    /* 重置计数 */
                    g_safety_ctx.detect_count = 0;
                    g_safety_ctx.anti_pinch_triggered = false;
                }
            } else {
                /* 超出检测范围，重置计数 */
                g_safety_ctx.detect_count = 0;
            }
        } else {
            /* 未检测到目标，重置计数 */
            g_safety_ctx.detect_count = 0;
        }

        pthread_mutex_unlock(&g_safety_ctx.mutex);
    }

    printf("[SAFETY] Detection task stopped\n");

    return NULL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int safety_init(const safety_config_t *config)
{
    if (g_safety_ctx.initialized) {
        printf("[SAFETY] Warning: already initialized\n");
        return 0;
    }

    /* 使用默认配置或用户配置 */
    if (config != NULL) {
        memcpy(&g_safety_ctx.config, config, sizeof(safety_config_t));
    } else {
        g_safety_ctx.config.anti_pinch_threshold = DEFAULT_THRESHOLD;
        g_safety_ctx.config.check_interval_ms = DEFAULT_CHECK_INTERVAL;
        g_safety_ctx.config.detection_range_cm = DEFAULT_RANGE_CM;
    }

    /* 初始化互斥锁 */
    pthread_mutex_init(&g_safety_ctx.mutex, NULL);

    /* 初始化状态 */
    g_safety_ctx.detect_count = 0;
    g_safety_ctx.anti_pinch_triggered = false;
    g_safety_ctx.running = false;
    g_safety_ctx.initialized = true;

    printf("[SAFETY] Initialized successfully\n");
    printf("[SAFETY]   Threshold: %d\n", g_safety_ctx.config.anti_pinch_threshold);
    printf("[SAFETY]   Check interval: %u ms\n", g_safety_ctx.config.check_interval_ms);
    printf("[SAFETY]   Detection range: %u cm\n", g_safety_ctx.config.detection_range_cm);

    return 0;
}

int safety_deinit(void)
{
    if (!g_safety_ctx.initialized) {
        return 0;
    }

    /* 停止检测任务 */
    safety_stop();

    /* 销毁互斥锁 */
    pthread_mutex_destroy(&g_safety_ctx.mutex);

    g_safety_ctx.initialized = false;

    printf("[SAFETY] Deinitialized\n");

    return 0;
}

int safety_start(void)
{
    if (!g_safety_ctx.initialized) {
        printf("[SAFETY] Error: not initialized\n");
        return -1;
    }

    if (g_safety_ctx.running) {
        printf("[SAFETY] Warning: already running\n");
        return 0;
    }

    g_safety_ctx.running = true;

    int ret = pthread_create(&g_safety_ctx.safety_thread, NULL,
                             safety_task, NULL);
    if (ret != 0) {
        printf("[SAFETY] Failed to create safety thread: %d\n", ret);
        g_safety_ctx.running = false;
        return -1;
    }

    printf("[SAFETY] Detection started\n");

    return 0;
}

int safety_stop(void)
{
    if (!g_safety_ctx.running) {
        return 0;
    }

    g_safety_ctx.running = false;
    pthread_join(g_safety_ctx.safety_thread, NULL);

    printf("[SAFETY] Detection stopped\n");

    return 0;
}

int radar_get_status(radar_result_t *result)
{
    if (result == NULL) {
        return -1;
    }

    return radar_read_data(result);
}

bool safety_is_anti_pinch_triggered(void)
{
    return g_safety_ctx.anti_pinch_triggered;
}

void safety_reset(void)
{
    pthread_mutex_lock(&g_safety_ctx.mutex);

    g_safety_ctx.detect_count = 0;
    g_safety_ctx.anti_pinch_triggered = false;

    pthread_mutex_unlock(&g_safety_ctx.mutex);

    printf("[SAFETY] Reset\n");
}

